import{_ as n,C as a,o as c,c as s,ai as e,E as o,j as r,a as i}from"./chunks/framework.C7mMih4h.js";const b=JSON.parse('{"title":"Masonry 瀑布流","description":"","frontmatter":{"title":"Masonry 瀑布流","outline":[2,3]},"headers":[],"relativePath":"components/masonry.md","filePath":"components/masonry.md","lastUpdated":1791429948000}'),l={name:"components/masonry.md"};function m(h,t,g,p,_,y){const d=a("DemoPreview");return c(),s("div",null,[t[0]||(t[0]=e('<div><p>瀑布流布局：条目按「当前最矮的一列」依次落位，高度<strong>实测</strong>而非预设。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>内容高度参差不齐，但希望整体视觉上「填满」容器（图片墙、卡片流、商品列表）。</li><li>需要按断点控制列数与间距。</li></ul></div><h2 id="代码演示" tabindex="-1">代码演示 <a class="header-anchor" href="#代码演示" aria-label="Permalink to &quot;代码演示&quot;">​</a></h2><div><p><strong>basic</strong>：瀑布流布局：条目按「当前最矮的一列」依次落位。 ⚠️ antd 的 demo 用 <code>Card</code> 渲染条目，本仓 Card 尚未落地 ⇒ 用<strong>原生 div + 等价内联样式</strong>替换。</p></div>',3)),o(d,{component:"masonry",demo:"basic"}),t[1]||(t[1]=e("<div><p><strong>dynamic</strong>：增删条目；<code>onLayoutChange</code> 把算出来的列号写回 <code>items</code>，写回后条目就「钉」在该列。 ⚠️ 与 antd 的 demo 有两处<strong>有意</strong>差异：① 新增条目的高度用确定值 （上游用 <code>Math.random()</code>，每次渲染都不同 ⇒ demo 冒烟测试不可复现）； ② <code>Card</code> / <code>CloseOutlined</code> 用原生 div / 文本 <code>×</code> 替换（本仓 Card 尚未落地）。</p></div>",1)),o(d,{component:"masonry",demo:"dynamic"}),t[2]||(t[2]=e("<div><p><strong>fresh</strong>：条目内容高度会变时用 <code>fresh</code> —— 它给<strong>每个条目</strong>各挂一个 <code>ResizeObserver</code>， 点一下就重新量测并重排。 ⚠️ <code>fresh</code> <strong>不改变 DOM 结构</strong>（观察器不产节点，上游的 <code>ResizeObserver</code> 是 <code>cloneElement</code>）。 与 antd 的 demo 的差异：高度用确定值而不是 <code>Math.random()</code>。</p></div>",1)),o(d,{component:"masonry",demo:"fresh"}),t[3]||(t[3]=e("<div><p><strong>image</strong>：条目是图片。图片<strong>加载后</strong>才有真实高度 ⇒ 需要重新量测。 ⚠️ 上游把 <code>onLoad</code> / <code>onError</code> 挂在根 <code>div</code> 上，但那条路径<strong>实际是死代码</strong> （React 把 <code>load</code> 当非委托事件直接绑在该元素、冒泡阶段，而 <code>load</code> 不冒泡 ⇒ 子 <code>&lt;img&gt;</code> 的事件到不了根 <code>div</code>）。本仓<strong>照抄同样的绑定</strong>，行为与 antd 一致。 需要「内容尺寸变化就重排」时请用 <code>fresh</code>。</p></div>",1)),o(d,{component:"masonry",demo:"image"}),t[4]||(t[4]=r("div",null,[r("p",null,[r("strong",null,"responsive"),i("：列数与间距都支持按断点配置 —— 命中规则是「从大到小取第一个已配置的断点」。")])],-1)),o(d,{component:"masonry",demo:"responsive"}),t[5]||(t[5]=e("<div><p><strong>style-class</strong>：<code>classNames</code> / <code>styles</code> 两个语义槽都支持<strong>对象</strong>与<strong>函数</strong>两种形态； 函数形态的入参 <code>props.columns</code> 是<strong>解析后的列数</strong>（不是原始 prop）。 ⚠️ 与 antd 的 demo 的差异：上游用 <code>antd-style</code> 的 <code>createStaticStyles</code> 生成类名， 本仓没有这个依赖 ⇒ 用普通类名替换；<code>Flex</code> / <code>Divider</code> / <code>Typography</code> 换成原生元素。 <strong>缺口登记在 <code>README.md</code> §7。</strong></p></div>",1)),o(d,{component:"masonry",demo:"style-class"}),t[6]||(t[6]=e('<div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>类型</th><th>默认值</th><th>全局配置</th></tr></thead><tbody><tr><td>items</td><td>数据源。每项 <code>{ key, data, column?, height?, children? }</code></td><td><code>MasonryItemType&lt;T&gt;[]</code></td><td>—</td><td>×</td></tr><tr><td>itemRender</td><td>单项渲染。<strong>优先级低于</strong> <code>item.children</code></td><td><code>(info: MasonryItemRenderInfo&lt;T&gt;) =&gt; VNodeChild</code></td><td>—</td><td>×</td></tr><tr><td>columns</td><td>列数。对象形态按断点解析（从大到小取第一个已配置的断点；都没命中 ⇒ <code>columns.xs ?? 1</code>）</td><td><code>number | Partial&lt;Record&lt;Breakpoint, number&gt;&gt;</code></td><td><code>3</code></td><td>×</td></tr><tr><td>gutter</td><td>间距。复用 Grid 的 <code>Gutter</code>（数字 / 字符串 / 断点对象 / <code>[水平, 纵向]</code>）</td><td><code>Gutter</code></td><td><code>0</code></td><td>×</td></tr><tr><td>fresh</td><td>为<strong>每个条目</strong>各挂一个 <code>ResizeObserver</code>（内容高度会变时用）。⚠️ <strong>不改变 DOM 结构</strong></td><td><code>boolean</code></td><td><code>false</code></td><td>×</td></tr><tr><td>onLayoutChange</td><td>布局顺序变化时触发。载荷是 <strong><code>{...item, column}</code></strong>（item 本体被展开）</td><td><code>(sortInfo: MasonryLayoutItem&lt;T&gt;[]) =&gt; void</code></td><td>—</td><td>×</td></tr><tr><td>classNames</td><td>语义化类名（<code>root</code> / <code>item</code>），支持函数形态</td><td><code>MasonrySemanticClassNames | ((info) =&gt; …)</code></td><td>—</td><td>✅（<code>masonry.classNames</code>）</td></tr><tr><td>styles</td><td>语义化样式（<code>root</code> / <code>item</code>），支持函数形态</td><td><code>MasonrySemanticStyles | ((info) =&gt; …)</code></td><td>—</td><td>✅（<code>masonry.styles</code>）</td></tr><tr><td>prefixCls</td><td>类名前缀</td><td><code>string</code></td><td>从 ConfigProvider 取，兜底 <code>apollo-masonry</code></td><td>×</td></tr><tr><td>class / style</td><td><strong>根元素原生 attrs</strong>（不是 Props）</td><td><code>string | array | object</code> / <code>CSSProperties</code></td><td>—</td><td>×</td></tr><tr><td>style</td><td>根元素内联样式。<strong>会覆盖算出来的容器高度</strong></td><td><code>CSSProperties</code></td><td>—</td><td>×</td></tr></tbody></table><h4 id="masonryitemtype" tabindex="-1">MasonryItemType <a class="header-anchor" href="#masonryitemtype" aria-label="Permalink to &quot;MasonryItemType&quot;">​</a></h4><table tabindex="0"><thead><tr><th>字段</th><th>说明</th><th>类型</th><th>默认值</th></tr></thead><tbody><tr><td>key</td><td>唯一标识（数字会内部 <code>String()</code> 化）</td><td><code>string | number</code></td><td>—</td></tr><tr><td>data</td><td>业务数据，原样透传给 <code>itemRender</code></td><td><code>T</code></td><td>—</td></tr><tr><td>column</td><td>指定落在第几列（0 基）。超界会夹到最后一列</td><td><code>number</code></td><td>自动选最矮列</td></tr><tr><td>height</td><td>⚠️ <strong>上游声明了但从不读</strong> —— 高度一律实测</td><td><code>number</code></td><td>—</td></tr><tr><td>children</td><td>内容。<strong>优先于</strong> <code>itemRender</code></td><td><code>VNodeChild</code></td><td>—</td></tr></tbody></table><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>说明</th><th>参数</th></tr></thead><tbody><tr><td>layoutChange</td><td>布局顺序变化（= <code>onLayoutChange</code>，两者<strong>同时</strong>发出）</td><td><code>(sortInfo: MasonryLayoutItem&lt;T&gt;[])</code></td></tr></tbody></table><h3 id="ref" tabindex="-1">Ref <a class="header-anchor" href="#ref" aria-label="Permalink to &quot;Ref&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>nativeElement</td><td><code>() =&gt; HTMLDivElement | null</code></td><td>根元素（对应 antd 的 forwardRef ref）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p><strong>没有插槽</strong> —— 上游从不读 <code>children</code>，内容一律走 <code>items</code> + <code>itemRender</code> / <code>item.children</code>。</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><h3 id="component-token" tabindex="-1">Component Token <a class="header-anchor" href="#component-token" aria-label="Permalink to &quot;Component Token&quot;">​</a></h3><p>Masonry <strong>没有 Component Token</strong>（与 antd 逐字一致：<code>ComponentToken</code> 是空接口）。 它只消费全局 alias：</p><table tabindex="0"><thead><tr><th>token</th><th>用在哪</th></tr></thead><tbody><tr><td><code>motionDurationSlow</code></td><td>条目淡入（<code>-fade-appear</code>）与位置过渡</td></tr><tr><td><code>motionDurationFast</code></td><td>条目淡出（<code>-fade-leave</code>）</td></tr><tr><td><code>motionEaseOut</code></td><td>上述三条的缓动</td></tr></tbody></table><h2 id="设计说明" tabindex="-1">设计说明 <a class="header-anchor" href="#设计说明" aria-label="Permalink to &quot;设计说明&quot;">​</a></h2><ul><li><strong>排布算法</strong>：按 <code>items</code> 顺序，每项落到<strong>当前累计高度最小</strong>的那一列（平局取<strong>最左</strong>）； 容器高度 = 最高列 − 一个纵向间距。详见 <code>hooks/positions.ts</code> 的文件头（含三处易错点）。</li><li><strong>高度是实测的</strong>：<code>item.height</code> 从不被读；首帧量测在 commit 之后（复刻上游 <code>useEffect</code> 的时机）。</li><li><strong><code>onLoad</code> / <code>onError</code> 是死监听</strong>：上游把它挂在根 <code>div</code> 上，但 React 的 <code>load</code> 是非委托事件、 绑在该元素且<strong>冒泡</strong>阶段，而 <code>load</code> 不冒泡 ⇒ 子 <code>&lt;img&gt;</code> 的事件到不了根。本仓<strong>照抄同样的绑定</strong> （行为与 antd 一致）。需要「内容尺寸变化就重排」时请用 <code>fresh</code>。</li><li><strong>本组件零 ARIA</strong>：容器与条目都是普通 <code>div</code>（无 <code>role</code>、无 <code>tabindex</code>）—— 语义完全由 <code>itemRender</code> 的内容负责。这是上游的<strong>有意</strong>设计，已由 L5 钉住。</li><li><strong>不透传 attrs</strong>：上游不展开 <code>...restProps</code> ⇒ 本仓设了 <code>inheritAttrs: false</code>。</li></ul></div>',1))])}const T=n(l,[["render",m]]);export{b as __pageData,T as default};
